/**
 * Decodes octets to characters using the UTF-8 decoding and appends the characters to a StringBuffer.
 * @return the index to the next unchecked character in the string to decode
 */
private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int b = bb.get(i) & 0xFF;
    switch (b >> 4) {
        case 0:
        case 1:
        case 2:
        case 3:
        case 4:
        case 5:
        case 6:
        case 7:
            sb.append((char) b);
            i += 1;
            break;
        case 12:
        case 13:
            int charValue = (b & 0x1F) << 6;
            int b2 = bb.get(i + 1) & 0xFF;
            charValue |= (b2 & 0x3F);
            sb.append((char) charValue);
            i += 2;
            break;
        case 14:
            int u16Value = (b & 0x0F) << 12;
            char c;
            int b2_ = bb.get(i + 1) & 0xFF;
            int b3 = bb.get(i + 2) & 0xFF;
            u16Value |= (b2_ & 0x3F) << 6;
            u16Value |= (b3 & 0x3F);
            try {
                c = (char) u16Value;
            } catch (Exception e) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            sb.append(c);
            i += 3;
            break;
        case 15:
            long u32Value = (b & 0x7L) << 18;
            int b2__ = bb.get(i + 1) & 0xFF;
            int b3_ = bb.get(i + 2) & 0xFF;
            int b4 = bb.get(i + 3) & 0xFF;
            u32Value |= (b2__ & 0x3FL) << 12;
            u32Value |= (b3_ & 0x3FL) << 6;
            u32Value |= (b4 & 0x3FL);
            int lowChar = (int) (u32Value - 0x10000);
            sb.append((char) (0xD800 + (lowChar >>> 10)));
            sb.append((char) (0xDC00 + (lowChar & 0x3FF)));
            i += 4;
            break;
        default:
            throw new IllegalArgumentException("Invalid UTF-8 leading byte at index " + i);
    }
    return i;
}
