public static int nullSafeHashCode(long[] array){
    if (array == null) {
        return 0;
    }
    int hashCode = 17;
    for (int i = 0; i < array.length; i++) {
        long bits = array[i];
        int intBits = (int) (bits ^ (bits >>> 32));
        hashCode = 31 * hashCode + intBits;
    }
    return hashCode;
}
