public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] arguments = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type typeArg = actualTypeArguments[i];
        if (typeArg instanceof Class) {
            arguments[i] = (Class<?>) typeArg;
        } else if (typeArg instanceof WildcardType) {
            WildcardType wildcardType = (WildcardType) typeArg;
            Type[] upperBounds = wildcardType.getUpperBounds();
            if (upperBounds.length > 0 && upperBounds[0] instanceof Class) {
                arguments[i] = (Class<?>) upperBounds[0];
            } else {
                return null;
            }
        } else if (typeArg instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArg;
            Map<String, Type> typeArgMap = resolveTypeVariables(targetType, parameterizedType.getRawType().getClass());
            Type resolvedType = typeArgMap.get(typeVariable.getName());
            if (resolvedType instanceof Class) {
                arguments[i] = (Class<?>) resolvedType;
            } else {
                return null;
            }
        } else {
            return null;
        }
    }
    return arguments;
}

private static Map<String, Type> resolveTypeVariables(Class<?> targetType, Class<?> rawType) {
    Map<String, Type> result = new HashMap<>();
    if (targetType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) targetType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        TypeVariable<?>[] typeParameters = rawType.getTypeParameters();
        for (int i = 0; i < typeParameters.length && i < actualTypeArguments.length; i++) {
            result.put(typeParameters[i].getName(), actualTypeArguments[i]);
        }
    }
    return result;
}
