public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    int size = 0;
    int endIndex = index + len;
    if (index < 0) {
        index = 0;
    }
    if (endIndex > str.length()) {
        endIndex = str.length();
    }
    if (index > endIndex) {
        return 0;
    }
    for (int i = index; i < endIndex; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

