public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value != null) {
        // Perform variable substitution on the found value
        String substituted = substituteVars(value, props);
        return substituted;
    }
    return null;
}

private static String substituteVars(String value, Properties props) {
    int startIndex = value.indexOf("${");
    while (startIndex != -1) {
        int endIndex = value.indexOf('}', startIndex + 2);
        if (endIndex == -1) {
            break;
        }
        String varName = value.substring(startIndex + 2, endIndex);
        String varValue = props.getProperty(varName);
        if (varValue == null) {
            varValue = "";
        }
        value = value.substring(0, startIndex) + varValue + value.substring(endIndex + 1);
        startIndex = value.indexOf("${");
    }
    return value;
}
