public static String sessionId() {
    try {
        // Generate a random number
        int randomNum = new SecureRandom().nextInt();
        // Convert random number to string
        String randomStr = Integer.toString(randomNum);
        // Create a hash of the random string
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(randomStr.getBytes());
        // Convert the hash to a hex string
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b & 0xff));
        }
        return sb.toString();
    } catch (NoSuchAlgorithmException e) {
        // Fallback: generate a simple unique ID based on time and random
        return "session-" + System.currentTimeMillis() + "-" + new SecureRandom().nextInt();
    }
}
