        return str == null && suffix == null;
    }
    if (suffix.length() > str.length()) {
        return false;
    }
    if (ignoreCase) {
        final String strLower = str.slice(str.length() - suffix.length()).toLowerCase();
        final String suffixLower = suffix.toLowerCase();
        return strLower.equals(suffixLower);
    }
    return str.endsWith(suffix);
}

