    int high = read();
    if (high == -1) {
        throw new EOFException();
    }
    int len = high & 0x7f;
    if (high >= 0x80) {
        if (high >= 0xfc) {
            throw new IOException("Unknown length type " + Integer.toHexString(high));
        }
        low = len & 0x1f;
        int tempLen;
        switch (high & 0x1f) {
            case 1:
                break;
            case 2:
                tempLen = read();
                if (tempLen == -1) {
                    throw new EOFException();
                }
                len = (low << 8) + (tempLen & 0xff);
                break;
            case 3:
                tempLen = read();
                if (tempLen == -1) {
                    throw new EOFException();
                }
                low = tempLen & 0xff;
                tempLen = read();
                if (tempLen == -1) {
                    throw new EOFException();
                }
                len = (low << 8) + (tempLen & 0xff);
                break;
            case 4:
                throw new IOException("String length too large: " + Integer.toHexString(high));
        }
    }
