protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        return new GraphPath<>();
    }

    // Build adjacency information from the tour edges
    Map<V, Map<V, E>> adjacency = new HashMap<>();
    for (E edge : tour) {
        V src = graph.getEdgeSource(edge);
        V tgt = graph.getEdgeTarget(edge);

        adjacency.computeIfAbsent(src, k -> new HashMap<>()).put(tgt, edge);
        adjacency.computeIfAbsent(tgt, k -> new HashMap<>()).put(src, edge);
    }

    // Find the start node (a node with degree 2, pick any)
    V start = null;
    for (V node : adjacency.keySet()) {
        start = node;
        break;
    }

    // Traverse the tour starting from the start node
    List<E> order = new ArrayList<>();
    V current = start;
    V previous = null;

    while (true) {
        Map<V, E> neighbors = adjacency.get(current);
        if (neighbors == null || neighbors.isEmpty()) {
            break;
        }

        V next = null;
        E edge = null;
        for (Map.Entry<V, E> entry : neighbors.entrySet()) {
            if (!entry.getKey().equals(previous)) {
                next = entry.getKey();
                edge = entry.getValue();
                break;
            }
        }

        if (edge == null) {
            // All neighbors are previous, we should have completed the circuit
            break;
        }

        order.add(edge);
        previous = current;
        current = next;

        // If we've visited all edges, stop
        if (order.size() == tour.size()) {
            break;
        }

        // If we're back to start, also stop
        if (current.equals(start)) {
            break;
        }
    }

    return new GraphPath<>(order);
}
