public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        path = "";
    }
    if (relativePath == null) {
        return path;
    }
    // Normalize separators for both paths
    StringBuilder normalizedPath = new StringBuilder(path.replace('\\', '/'));
    StringBuilder normalizedRelative = new StringBuilder(relativePath.replace('\\', '/'));

    // If the path is empty, just return the normalized relative path (but clean it)
    if (normalizedPath.length() == 0) {
        return cleanupPath(normalizedRelative.toString());
    }

    // If the relative path is empty, return the normalized original path
    if (normalizedRelative.length() == 0) {
        return cleanupPath(normalizedPath.toString());
    }

    String result = normalizedPath.toString() + "/" + normalizedRelative.toString();

    // Handle common relative segments: . and ..
    // This is a simple approach to resolve . and .. segments
    String[] parts = result.split("/");
    Stack<String> resolvedParts = new Stack<>();
    for (String part : parts) {
        if (part.equals("..")) {
            if (!resolvedParts.isEmpty()) {
                resolvedParts.pop();
            }
        } else if (!part.equals(".") && !part.isEmpty()) {
            resolvedParts.push(part);
        }
    }

    // Build the final string
    StringBuilder finalResult = new StringBuilder();
    // If the original path was absolute (starts with /), keep it absolute
    boolean isAbsolute = normalizedPath.toString().startsWith("/");
    if (isAbsolute) {
        finalResult.append("/");
    }
    for (int i = 0; i < resolvedParts.size(); i++) {
        if (i > 0) {
            finalResult.append("/");
        }
        finalResult.append(resolvedParts.get(i));
    }

    return finalResult.toString();
}

private static String cleanupPath(String path) {
    // This helper just normalizes the path, but we do the main logic in applyRelativePath
    // For now, just return the path as is, or we could clean it up here too
    // but the main method does the resolution
    return path;
}
